 5	    private static void siftDown(int[] values, int heapSize, int startIndex) {
 6	        int currentIndex = startIndex;
 7	
 8	        while (true) {
 9	            int largestIndex = currentIndex;
10	            int leftChildIndex = leftChildIndex(currentIndex);
11	            int rightChildIndex = rightChildIndex(currentIndex);
12	
13	            if (leftChildIndex < heapSize && values[leftChildIndex] > values[largestIndex]) {
14	                largestIndex = leftChildIndex;
15	            }
16	
17	            if (rightChildIndex < heapSize && values[rightChildIndex] > values[largestIndex]) {
18	                largestIndex = rightChildIndex;
19	            }
20	
21	            if (largestIndex == currentIndex) {
22	                return;
23	            }
24	
25	            swap(values, currentIndex, largestIndex);
26	            currentIndex = largestIndex;
27	        }
28	    }
29	
30	    private static int leftChildIndex(int index) {
31	        return 2 * index + 1;
32	    }
33	
34	    private static int rightChildIndex(int index) {
35	        return 2 * index + 2;
36	    }
37	
38	    private static void swap(int[] values, int firstIndex, int secondIndex) {
39	        int temp = values[firstIndex];
40	        values[firstIndex] = values[secondIndex];
41	        values[secondIndex] = temp;
42	    }
43	
44	    static void buildHeap(int[] values) {
45	        for (int index = lastParentIndex(values.length); index >= 0; index--) {
46	            siftDown(values, values.length, index);
47	        }
48	    }
49	
50	    private static int lastParentIndex(int heapSize) {
51	        return heapSize / 2 - 1;
52	    }
